def _task():
    try: return asyncio.current_task()
    except RuntimeError: return None

def _need(value):
    if not value: raise ValueError('source_operation_refused')

def _stamp(info):
    return (info.st_dev, info.st_ino, info.st_uid, info.st_gid, info.st_mode,
            info.st_nlink, info.st_size, info.st_mtime_ns, info.st_ctime_ns)

def _root(value):
    root = Path(value)
    _need(root.is_absolute() and root.resolve(strict=True) == root)
    parents = (root, *root.parents)
    _need(all(stat.S_ISDIR(os.lstat(p).st_mode) and not stat.S_ISLNK(os.lstat(p).st_mode)
              for p in parents))
    return root

def _read(path, limit=1048576):
    path = Path(path)
    parents = [(p, os.lstat(p)) for p in path.parents]
    _need(all(stat.S_ISDIR(s.st_mode) and not stat.S_ISLNK(s.st_mode) for _, s in parents))
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        before = os.fstat(fd)
        _need(stat.S_ISREG(before.st_mode) and before.st_uid == os.getuid()
              and before.st_nlink == 1 and not before.st_mode & 0o022
              and 0 < before.st_size <= limit)
        chunks = bytearray()
        while len(chunks) < before.st_size:
            chunk = os.read(fd, min(65536, before.st_size - len(chunks)))
            _need(bool(chunk)); chunks.extend(chunk)
        _need(_stamp(before) == _stamp(os.fstat(fd)) == _stamp(os.lstat(path)))
        for parent, was in parents:
            now = os.lstat(parent)
            _need((was.st_dev, was.st_ino, was.st_uid, was.st_gid, was.st_mode) ==
                  (now.st_dev, now.st_ino, now.st_uid, now.st_gid, now.st_mode))
        return bytes(chunks), _stamp(before)
    finally: os.close(fd)

def _inventory(root):
    found = {}
    for directory, dirs, files in os.walk(root, followlinks=False):
        directory = Path(directory)
        if directory == root:
            dirs[:] = [d for d in dirs if d != '.git']
            files = [f for f in files if f != '.git']
        for name in list(dirs):
            path = directory / name
            if path.is_symlink():
                dirs.remove(name); files.append(name)
        for name in files:
            path = directory / name; info = os.lstat(path)
            mode = ('120000' if stat.S_ISLNK(info.st_mode) else
                    '100755' if stat.S_ISREG(info.st_mode) and info.st_mode & 0o111 else
                    '100644' if stat.S_ISREG(info.st_mode) else 'invalid')
            found[str(path.relative_to(root))] = mode
    return found



