def _held_media_current_pins(entries,metadata):
    # Fixed native-stage predecessor DATA, never runtime Git or a prefix skip.
    _need(type(MEDIA_STAGE_PREDECESSOR) is dict and
          hashlib.sha256(json.dumps(MEDIA_STAGE_PREDECESSOR,sort_keys=True,separators=(',',':')).encode()).hexdigest()==MEDIA_STAGE_PREDECESSOR_SHA256)
    _need(type(entries) is dict and type(metadata) is dict)
    expected=MEDIA_STAGE_PREDECESSOR['pins'];_need(len(expected)==7)
    result={}
    for path,prior in expected.items():
        _need(path in entries and entries[path]=={'bytes':prior['bytes'],'sha256':prior['sha256']})
        _need(path in metadata and type(metadata[path]) is dict and
              set(metadata[path])=={'bytes','sha256','target_bytes','target_sha256','target_zlib_base64'})
        result[path]=_source_pin(metadata[path])
    return result

def _read_held_media(root,path,pin):
    _need(path in MEDIA_STAGE_PREDECESSOR['pins'])
    target=Path(root)/path;info=os.lstat(target)
    _need(stat.S_ISREG(info.st_mode) and stat.S_IMODE(info.st_mode)==0o644)
    raw,stamp=_read(target)
    _need(stat.S_ISREG(stamp[4]) and stat.S_IMODE(stamp[4])==0o644)
    _need(len(raw)==pin['bytes'] and hashlib.sha256(raw).hexdigest()==pin['sha256'])
    return raw,stamp

def _registry_object(pairs):
    result={}
    for key,value in pairs:
        _need(type(key) is str and key not in result);result[key]=value
    return result

def _relative_source_path(path):
    _need(type(path) is str and bool(path) and not path.startswith('/') and '\\' not in path and ':' not in path)
    _need(all(ord(c)>=32 and ord(c)!=127 for c in path))
    parts=path.split('/')
    _need(all(part not in ('','.','..') and part.lower()!='.git' for part in parts))
    return path

def _source_pin(row):
    _need(type(row) is dict and 'bytes' in row and 'sha256' in row)
    count=row['bytes'];digest=row['sha256']
    _need(type(count) is int and 0<count<=1048576 and type(digest) is str and len(digest)==64
          and all(c in '0123456789abcdef' for c in digest))
    return {'bytes':count,'sha256':digest}

def _authenticate_registry(raw,metadata):
    _need(type(raw) is bytes and REGISTRY in metadata)
    pin=_source_pin(metadata[REGISTRY])
    _need(len(raw)==pin['bytes'] and hashlib.sha256(raw).hexdigest()==pin['sha256'])
    return pin

def _baseline_metadata():
    # Immutable actual20b public blob DATA, not executable historical code.
    # Generated/reviewed against Git once; archive/runtime input needs no .git or fallback.
    _need(type(BASE_ADMISSION_BYTES) is int and 0<BASE_ADMISSION_BYTES<=1048576)
    try:
        packed=base64.b64decode(BASE_ADMISSION_ZLIB_BASE64,validate=True)
        decoder=zlib.decompressobj();raw=decoder.decompress(packed,BASE_ADMISSION_BYTES+1)
    except (ValueError,zlib.error):
        raise ValueError('source_operation_refused') from None
    _need(decoder.eof and not decoder.unused_data and not decoder.unconsumed_tail)
    _need(len(raw)==BASE_ADMISSION_BYTES)
    _need(hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()==BASE_ADMISSION_BLOB)
    _need(hashlib.sha256(raw).hexdigest()==BASE_ADMISSION_SHA256)
    tree=ast.parse(raw)
    nodes=[n for n in tree.body if isinstance(n,ast.Assign) and len(n.targets)==1
           and isinstance(n.targets[0],ast.Name) and n.targets[0].id=='CURRENT_METADATA']
    _need(len(nodes)==1)
    value=ast.literal_eval(nodes[0].value);_need(type(value) is dict and len(value)==53)
    return value

def _check_historical_targets(metadata,baseline_metadata):
    _need(type(metadata) is dict and type(baseline_metadata) is dict)
    _need(set(baseline_metadata).issubset(metadata))
    for path,old in baseline_metadata.items():
        _need(type(old) is dict and type(metadata[path]) is dict)
        expected={k:v for k,v in old.items() if k.startswith('target_')}
        actual={k:v for k,v in metadata[path].items() if k.startswith('target_')}
        _need(actual==expected)

def _new_path_policy(paths,baseline,metadata,production,baseline_metadata):
    _need(type(paths) is list and len(paths)<=4096 and type(baseline) is dict)
    _need(type(metadata) is dict and type(production) is dict)
    _check_historical_targets(metadata,baseline_metadata)
    _need(len(paths)==len(set(_relative_source_path(p) for p in paths)))
    selected=set(paths);pins={}
    for path in selected:
        _need(path not in baseline)
        candidates=[_source_pin(group[path]) for group in (metadata,production) if path in group]
        _need(bool(candidates) and all(pin==candidates[0] for pin in candidates))
        pins[path]=candidates[0]
    declared=set(metadata)|set(production)
    _need(selected==declared-set(baseline))
    leaves=set(baseline)|selected
    for path in selected:
        parts=path.split('/')
        _need(not any('/'.join(parts[:i]) in leaves for i in range(1,len(parts))))
        _need(not any(other.startswith(path+'/') for other in leaves if other!=path))
    return pins

def _successor_policy(rows,baseline_entries,baseline_inventory,new_pins):
    _need(type(rows) is dict and type(baseline_entries) is dict)
    result=dict(baseline_entries)
    for path,row in rows.items():
        _relative_source_path(path);_need(path!=REGISTRY)
        _need(type(row) is dict and set(row)=={'baseline','current'})
        current=_source_pin(row['current']);_need(row['current']==current)
        if path in baseline_inventory:
            _need(path in baseline_entries and row['baseline'] is not None
                  and row['baseline']==baseline_entries[path])
        else:
            _need(path in new_pins and row['baseline'] is None and current==new_pins[path])
        result[path]=current
    return result

def _regular_new_source(root,path,pin):
    _relative_source_path(path);pin=_source_pin(pin);target=Path(root)/path
    info=os.lstat(target)
    _need(stat.S_ISREG(info.st_mode) and stat.S_IMODE(info.st_mode)==0o644)
    raw,stamp=_read(target)
    _need(stat.S_ISREG(stamp[4]) and stat.S_IMODE(stamp[4])==0o644)
    _need(len(raw)==pin['bytes'] and hashlib.sha256(raw).hexdigest()==pin['sha256'])
    return raw,stamp

class _CoordinatorView:
    __slots__ = ('_operation', '_module')
    def __init__(self, operation, module): self._operation=operation; self._module=module
    def assert_cohort(self, root, reader):
        op=self._operation;op.require(root)
        _need(getattr(reader,'__self__',None) is op and getattr(reader,'__func__',None) is SourceOperation.read_producer)
        return self._module.assert_cohort(root,reader)
    def source_view(self, path, raw):
        op=self._operation;op.require()
        _need(type(path) is str and type(raw) is bytes)
        _need(raw == op.read_producer(op.producer_root/path))
        return self._module.source_view(path,raw)

class _WorkerView:
    __slots__ = ('_operation', '_module', '_coordinator')
    def __init__(self, operation, module, coordinator):
        self._operation=operation;self._module=module;self._coordinator=coordinator
    def reduce_if_selected(self,path,raw):
        op=self._operation;op.require()
        expected=self._coordinator.source_view(path,op.read_producer(op.producer_root/path))
        _need(type(raw) is bytes and raw == expected)
        return self._module.reduce_if_selected(path,raw)

class _CalendarView:
    __slots__ = ('_operation', '_module')
    def __init__(self, operation, module):self._operation=operation;self._module=module
    def reduce_calendar_wire_union(self,raw):
        op=self._operation;op.require()
        path='support/governance/native-organization/test-native-organization-mysql.php'
        expected=op.coordinator.source_view(path,op.read_producer(op.producer_root/path))
        expected=op.worker_terminal.reduce_if_selected(path,expected)
        _need(type(raw) is bytes and raw == expected)
        return self._module.reduce_calendar_wire_union(raw)

class SourceOperation:
    def __init__(self, key, producer_root):
        _need(key is _KEY)
        self._roots = (_root(ROOT), _root(producer_root))
        self._state = 'new'; self._modules = {}; self._snapshots = {}; self._auxiliary_modules = []
        self._prepared_ledgers = {}
        _ISSUED.add(self)

    @property
    def code_root(self): return self._roots[0]
    @property
    def producer_root(self): return self._roots[1]
    @property
    def coordinator(self): return self._coordinator
    @property
    def worker_terminal(self): return self._worker_terminal
    @property
    def calendar_delta(self): return self._calendar_delta

    def require(self, root=None):
        _need(type(self) is SourceOperation and self in _ISSUED
              and self._state == 'active' and self._thread == threading.get_ident()
              and self._task is _task() and _ACTIVE.get() is self._token_identity)
        if root is not None: _need(_root(root) == self.producer_root)
        return self

    def _admitted_root(self, root=None):
        self.require()
        value = self.code_root if root is None else _root(root)
        _need(value in self._snapshots)
        return {'production_paths': 19, 'metadata_paths': len(admission.CURRENT_METADATA),
                'full_source_revision_authorized': False, 'runtime_qualified': False}

    def _capture_ancestor_identities(self):
        identities={}
        for root in dict.fromkeys((self.code_root,self.producer_root)):
            for path in (root,*root.parents):
                info=os.lstat(path)
                _need(stat.S_ISDIR(info.st_mode) and not stat.S_ISLNK(info.st_mode))
                identity=(info.st_dev,info.st_ino,info.st_uid,info.st_gid,info.st_mode)
                if path in identities:_need(identities[path] == identity)
                identities[path]=identity
        return MappingProxyType(identities)

    def _verify_ancestor_identities(self):
        self.require()
        for path,identity in self._ancestor_identities.items():
            info=os.lstat(path)
            _need(stat.S_ISDIR(info.st_mode) and not stat.S_ISLNK(info.st_mode))
            _need((info.st_dev,info.st_ino,info.st_uid,info.st_gid,info.st_mode) == identity)

    def __enter__(self):
        _need(self._state == 'new' and _ACTIVE.get() is None)
        self._thread = threading.get_ident(); self._task = _task()
        self._token_identity = object(); self._reset = _ACTIVE.set(self._token_identity)
        try:
            self._ancestor_identities=self._capture_ancestor_identities()
            # No registry field is trusted before actual current admission and external selfpin.
            for root in dict.fromkeys((self.code_root,self.producer_root)):
                admission.assert_current_recipe(root)
            registry_bytes, _ = _read(self.code_root / REGISTRY)
            registry_pin=_authenticate_registry(registry_bytes,admission.CURRENT_METADATA)
            self._registry_bytes = registry_bytes
            registry = json.loads(registry_bytes,object_pairs_hook=_registry_object)
            _need(registry['source_revision'] == '20b138b4cd9a2cf61522613b4a8e5e21eca7341b')
            _need(set(registry) == {'schema','source_revision','source_tree','entries','inventory_zlib_base64','inventory_sha256','inventory_bytes','expected_leaf_count','successor_entries','new_paths'})
            _need(registry['schema'] == 'source-operation-registry-v1' and registry['source_tree'] == '74ca6114980547fceb27aedf3a2464a4518fcc91')
            packed = base64.b64decode(registry['inventory_zlib_base64'], validate=True)
            decoder = zlib.decompressobj(); inventory_raw = decoder.decompress(packed, 2097153)
            _need(len(inventory_raw) <= 2097152 and decoder.eof and not decoder.unused_data and not decoder.unconsumed_tail)
            _need(len(inventory_raw) == registry['inventory_bytes'] and hashlib.sha256(inventory_raw).hexdigest() == registry['inventory_sha256'] == BASE_INVENTORY_SHA256)
            expected = json.loads(inventory_raw)
            _need(len(expected) == registry['expected_leaf_count'] == 9303)
            baseline_metadata=_baseline_metadata()
            new_pins=_new_path_policy(registry['new_paths'],expected,admission.CURRENT_METADATA,
                                      admission.description.CURRENT_PINS,baseline_metadata)
            baseline_inventory=dict(expected)
            for path in new_pins:expected[path]='100644'
            self._inventory_expected = MappingProxyType(expected)
            # Existing files require actual baseline entries; new files use current authenticated pins.
            self._entries = _successor_policy(registry['successor_entries'],registry['entries'],baseline_inventory,new_pins)
            # Existing fixed media leaves remain native-stage predecessors in R.
            # Full current admission above authenticates their current raw rows;
            # capture them with those pins without writing a hash back into R.
            self._held_media_pins=MappingProxyType(_held_media_current_pins(self._entries,admission.CURRENT_METADATA))
            self._entries.update(self._held_media_pins)
            # Registry's own bytes are held separately, then checked against the
            # full admission row when integrated; never store a recursive selfhash.
            self._entries[REGISTRY]=registry_pin
            for path,pin in new_pins.items():
                if path in self._entries:_need(self._entries[path]==pin)
                self._entries[path]=pin
            for path,row in admission.CURRENT_METADATA.items():
                _need(path in self._entries and all(row[k]==self._entries[path][k] for k in ('bytes','sha256')))
            for path,row in admission.description.CURRENT_PINS.items():
                _need(path in self._entries and row==self._entries[path])
            _need(len(admission.description.CURRENT_PINS)==19)
            for path in (admission.BRIDGE, admission.PREPARATION, admission.MANIFEST, REGISTRY):
                raw, _ = _read(self.code_root/path)
                self._entries[path] = {'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest()}
            _need(all(path in self._entries for path in new_pins))
            for root in dict.fromkeys((self.code_root, self.producer_root)):
                admission.assert_current_recipe(root)
                layout = _prepared_layout(root,self._inventory_expected)
                captured = {}
                for path, pin in self._entries.items():
                    raw, stamp = (_read_held_media(root,path,pin) if path in self._held_media_pins else _regular_new_source(root,path,pin) if path in new_pins else _read(root/path))
                    _need(len(raw) == pin['bytes'] and hashlib.sha256(raw).hexdigest() == pin['sha256'])
                    captured[path] = (raw, stamp)
                self._snapshots[root] = MappingProxyType(captured)
                self._prepared_ledgers[root] = PreparedLedger(_PREPARED_KEY,self,root,layout)
            self._new_pins=MappingProxyType(new_pins)
            self._state = 'active'
            self._build_graph()
            self._verify_ancestor_identities()
            for ledger in self._prepared_ledgers.values():ledger.verify_exit(self)
            return self
        except BaseException:
            self._state = 'failed'; _ACTIVE.reset(self._reset)
            raise

    def read_source(self, path):
        self.require(); path = Path(path)
        _need(path.is_absolute())
        matches = [(root, str(path.relative_to(root))) for root in self._snapshots if path.is_relative_to(root)]
        _need(len(matches) == 1)
        root, relative = matches[0]
        _need(relative in self._snapshots[root])
        return self._snapshots[root][relative][0]

    def read_producer(self, path):
        self.require(self.producer_root)
        path = Path(path); _need(path.is_relative_to(self.producer_root))
        relative = str(path.relative_to(self.producer_root))
        _need(relative in self._snapshots[self.producer_root])
        return self._snapshots[self.producer_root][relative][0]

    def _build_graph(self):
        self.require()
        original_import = builtins.__import__
        def private_import(name, globals=None, locals=None, fromlist=(), level=0):
            self.require(); _need(level == 0)
            if name in GRAPH: return build(name)
            _need(name.split('.')[0] in STDLIB)
            return original_import(name, globals, locals, fromlist, level)
        def build(name):
            self.require(); _need(name in GRAPH)
            if name in self._modules: return self._modules[name]
            relative = 'scripts/governance/'+name+'.py'
            raw = self.read_source(self.code_root/relative)
            module = ModuleType('source_operation_private_'+name)
            module.__file__ = str(self.code_root/relative)
            module.__dict__['__builtins__'] = {**vars(builtins), '__import__': private_import}
            self._modules[name] = module
            exec(compile(raw, module.__file__, 'exec'), module.__dict__)
            if name == 'project_description_source_delta': module.checked_bytes = self.read_source
            if name == 'project_description_admission_delta':
                module._constants = self.require
                module.assert_current_recipe = self._admitted_root
