    path=Path(path);parents=[(p,os.lstat(p)) for p in path.parents]
    _need(all(stat.S_ISDIR(s.st_mode) and not stat.S_ISLNK(s.st_mode) for _,s in parents))
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
