    data=json.loads(raw,object_pairs_hook=_cache_pairs,parse_constant=lambda value: (_need(False)))
    _need(type(data) is dict and type(data.get('__symbol_cache_version__')) is int and data['__symbol_cache_version__']==12 and len(data)<=16385)
    def name(value):return type(value) is str and 0<len(value)<=1024 and all(ord(c)>=32 and ord(c)!=127 for c in value)
    def mapping(value):
        _need(type(value) is dict or type(value) is list and value==[])
        return value if type(value) is dict else {}
    count=0
    for key,row in data.items():
        if key=='__symbol_cache_version__':continue
        _need(len(key)==32 and all(c in '0123456789abcdef' for c in key))
        _need(type(row) is dict and set(row)=={'have','need','xmap'})
        for field,allowed in (('have',{'class','function','interface','trait'}),('need',{'class','class/interface','function','interface'})):
            groups=mapping(row[field]);_need(set(groups)<=allowed)
            for symbols in groups.values():
                symbols=mapping(symbols);_need(len(symbols)<=16384)
                for symbol,position in symbols.items():
                    # Both native extractors emit one integer byte offset per symbol.
                    _need(name(symbol) and type(position) is int and 0<position<=16777216)
