def _prepared_layout(root,source_expected):
    policy=_prepared_policy();found=_inventory(root)
    _need(type(source_expected) in (dict,MappingProxyType))
    _need(all(path in found and found[path]==mode for path,mode in source_expected.items()))
    extra=set(found)-set(source_expected);catalog=policy['catalog'];archives=policy['archives']
    compiled={_PREPARED_INSTALLED_XHP,*_PREPARED_FRESH_XHP}
